    def build_records(raw_tuple_list):
        records = []
        for t in raw_tuple_list:
            ipo_id, name, isin, sec, ind, ann_d, anch_d, op_d, cl_d, allot_d, list_d, sz, fresh, ofs, pl, ph, lot, fv, sh, qib_sh, nii_sh, ret_sh, qib_q, nii_q, ret_q, rev, rev_cg, pat, pat_cg, ebit, eps, roe, roce, de, ocf, pe, pb, ind_pe, n1, n5, n20, s1, s5, s20, vix, vix_cg, trend, gmp, gmp_pct, news_c, sent_s, pos_r, qib_s, nii_s, ret_s, tot_s = t
            slug = name.lower().replace(" ltd", "").replace(" limited", "").replace(" (", "_").replace(")", "").replace(" ", "_")
            r = {
                "ipo_id": ipo_id,
                "company_name": name,
                "normalized_company_name": slug,
                "isin": isin,
                "exchange": "NSE/BSE",
                "ipo_type": "MAINBOARD",
                "sector": sec,
                "industry": ind,
                "announcement_date": ann_d,
                "anchor_date": anch_d,
                "ipo_open_date": op_d,
                "ipo_close_date": cl_d,
                "allotment_date": allot_d,
                "listing_date": list_d,
                "feature_cutoff_datetime": f"{op_d}T09:59:59+05:30",
                "issue_size_in_crore": sz,
                "fresh_issue_in_crore": fresh,
                "ofs_in_crore": ofs,
                "price_low": pl,
                "price_high": ph,
                "lot_size": lot,
                "face_value": fv,
                "shares_offered": sh,
                "qib_shares_offered": qib_sh,
                "nii_shares_offered": nii_sh,
                "retail_shares_offered": ret_sh,
                "employee_shares_offered": 0,
                "qib_quota_pct": qib_q,
                "nii_quota_pct": nii_q,
                "retail_quota_pct": ret_q,
                "revenue_latest_cr": rev,
                "revenue_cagr_3yr": rev_cg,
                "pat_latest_cr": pat,
                "pat_cagr_3yr": pat_cg,
                "ebitda_margin_pct": ebit,
                "eps_pre_ipo": eps,
                "roe_pct": roe,
                "roce_pct": roce,
                "debt_equity_ratio": de,
                "operating_cash_flow_cr": ocf,
                "pe_ratio": pe,
                "pb_ratio": pb,
                "industry_pe": ind_pe,
                "nifty_1d_return": n1,
                "nifty_5d_return": n5,
                "nifty_20d_return": n20,
                "sensex_1d_return": s1,
                "sensex_5d_return": s5,
                "sensex_20d_return": s20,
                "india_vix": vix,
                "india_vix_5d_change": vix_cg,
                "market_trend": trend,
                "gmp_in_inr": gmp,
                "gmp_percentage": gmp_pct,
                "news_count": news_c,
                "average_sentiment_score": sent_s,
                "positive_news_ratio": pos_r,
                "qib_subscription": qib_s,
                "nii_subscription": nii_s,
                "retail_subscription": ret_s,
                "employee_subscription": 0.0,
                "total_subscription": tot_s,
                "daily": make_daily(op_d, cl_d, qib_s, nii_s, ret_s, tot_s)
            }
            records.append(r)
        return records

    return build_records(r2021), build_records(r2022), build_records(r2023), build_records(r2024)
